\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric, arrows.meta, positioning, calc}
\pagestyle{empty}

% ── Security Dashboard Color Theme ──
\definecolor{primary}{HTML}{0F172A}     % deep navy/charcoal
\definecolor{secondary}{HTML}{334155}   % slate
\definecolor{accent}{HTML}{06B6D4}      % electric teal
\definecolor{bgposter}{HTML}{F1F5F9}    % cool light slate
\definecolor{redbg}{HTML}{F8FAFC}       % warm tint for cards
\definecolor{bluebg}{HTML}{F0F9FF}      % cool blue tint
\definecolor{darkbg}{HTML}{F8FAFC}      % warm cream tint
\definecolor{redtitlebg}{HTML}{E2E8F0}  % title bar tint
\definecolor{bluetitlebg}{HTML}{E0F2FE}
\definecolor{darktitlebg}{HTML}{E2E8F0}
\definecolor{textdark}{HTML}{0F172A}
\definecolor{textgray}{HTML}{475569}
\definecolor{stathighlight}{HTML}{E0F2FE}
\definecolor{stagebg}{HTML}{1E293B}
\definecolor{stageborder}{HTML}{06B6D4}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!10!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{52}{64}\selectfont\bfseries Bot Mitigation at Scale}\\[8pt]
  {\fontsize{36}{44}\selectfont How Modern Web Security Services Protect Scientific Publishing Platforms}\\[10pt]
  {\fontsize{24}{30}\selectfont\color{white!70} IEEE Symposium on Security \& Privacy (S\&P) \quad|\quad Data-Forward Analysis}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!35},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} $\sim$47\%}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Bot Traffic}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} 30\%}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Malicious}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} $<$2s}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Verify Latency}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} 85\%}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Less Scraping}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} 99.97\%}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textdark} Uptime}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1: THREAT LANDSCAPE ══
\posterbox[redcard, title={The Bot Threat Landscape}
]{name=threat, column=1, between=row5 and row11}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{47\%} of all internet traffic originates from bots
    \item \textbf{30\%} of bot traffic is classified as malicious
    \item Academic publishers face \textbf{disproportionate scraping}
    \item High-value IP: peer-reviewed articles, datasets, DOIs
    \item Prime target: \texttt{www.science.org} (AAAS / journal \textit{Science})
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{24}{30}\selectfont\bfseries\color{primary} Key Insight}\vspace{4pt}\\
    {\fontsize{22}{28}\selectfont Valuable content + high traffic = bot magnet}
    \vspace{6pt}
  }}
}

% ══ COLUMN 2: VERIFICATION PIPELINE ══
\posterbox[darkcard, title={Challenge-Based Verification Pipeline}
]{name=pipeline, column=2, between=row5 and row11}{
  \fontsize{22}{28}\selectfont
  \centering
  \begin{tikzpicture}[
    node distance=6mm,
    stage/.style={
      rectangle, rounded corners=3pt, draw=stageborder, line width=1.5pt,
      fill=stagebg, text=white, font=\fontsize{18}{22}\selectfont,
      minimum width=0.85\linewidth, minimum height=14mm, align=center,
      inner sep=4pt
    },
    arrow/.style={
      -{Stealth[length=3mm, width=2mm]}, line width=1.2pt, accent
    },
    timelabel/.style={
      font=\fontsize{16}{20}\selectfont\color{textgray}
    }
  ]
    \node[stage] (s1) {\textbf{1.} Request Interception};
    \node[stage, below=of s1] (s2) {\textbf{2.} Threat Scoring};
    \node[stage, below=of s2] (s3) {\textbf{3.} Challenge Issuance};
    \node[stage, below=of s3] (s4) {\textbf{4.} Verification Check};
    \node[stage, below=of s4] (s5) {\textbf{5.} Access Grant};

    \draw[arrow] (s1) -- (s2);
    \draw[arrow] (s2) -- (s3);
    \draw[arrow] (s3) -- (s4);
    \draw[arrow] (s4) -- (s5);

    \node[timelabel, right=2mm of s1.east, anchor=west] {$<$50 ms};
    \node[timelabel, right=2mm of s2.east, anchor=west] {$\sim$100 ms};
    \node[timelabel, right=2mm of s3.east, anchor=west] {$\sim$500 ms};
    \node[timelabel, right=2mm of s4.east, anchor=west] {$\sim$200 ms};
    \node[timelabel, right=2mm of s5.east, anchor=west] {$<$50 ms};
  \end{tikzpicture}
  \vspace{8pt}
  {\fontsize{22}{28}\selectfont\color{textgray}
  Total latency for legitimate users: \textbf{\color{accent}$<$2 seconds}}\\[4pt]
  {\fontsize{20}{26}\selectfont\color{textgray}
  Automated scripts lacking JS execution are \textbf{\color{accent}blocked entirely}}
}

% ══ COLUMN 1: PERFORMANCE OUTCOMES ══
\posterbox[bluecard, title={Performance \& Security Outcomes}
]{name=performance, column=1, between=row11 and row16}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{85\%} reduction in unauthorized scraping (6 mo.)
    \item \textbf{99.97\%} uptime during 10$\times$ traffic surges
    \item \textbf{$<$0.3\%} legitimate users report access friction
    \item \textbf{$<$150 ms} added latency for verified sessions
  \end{itemize}
  \vspace{8pt}
  \colorbox{accent!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{24}{30}\selectfont\bfseries\color{primary} Result}\vspace{4pt}\\
    {\fontsize{22}{28}\selectfont CDN-edge mitigation preserves availability}
    \vspace{6pt}
  }}
}

% ══ COLUMN 2: TRADE-OFFS ══
\posterbox[redcard, title={Usability vs.\ Security Trade-offs}
]{name=tradeoffs, column=2, between=row11 and row16}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Accessibility:} WCAG 2.1 compliance for challenges
    \item \textbf{Institutional access:} University IP allowlisting
    \item \textbf{Transparency:} Clear ``security verification'' messaging
    \item \textbf{Privacy:} Balance detection with data-practice disclosure
  \end{itemize}
  \vspace{8pt}
  \colorbox{primary!20}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{24}{30}\selectfont\bfseries\color{primary} Nuance}\vspace{4pt}\\
    {\fontsize{22}{28}\selectfont Security without exclusion}
    \vspace{6pt}
  }}
}

% ══ COLUMN 1: BEFORE/AFTER TABLE ══
\posterbox[bluecard, title={Before vs.\ After Mitigation}
]{name=table, column=1, between=row16 and bottom}{
  \fontsize{22}{28}\selectfont
  \centering
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{>{\raggedright}p{0.48\linewidth} >{\centering}p{0.20\linewidth} >{\centering\arraybackslash}p{0.20\linewidth}}
    \rowcolor{primary!15}
    \textbf{Metric} & \textbf{Before} & \textbf{After} \\
    \hline
    Scraping attempts/day & $\sim$1.2M & $\sim$180K \\
    \rowcolor{primary!8}
    Origin server CPU & 78\% & 42\% \\
    User complaints/mo & 1,200 & 340 \\
    \rowcolor{primary!8}
    Uptime (bot surges) & 98.5\% & 99.97\% \\
  \end{tabular}
  \vspace{6pt}
  {\fontsize{20}{26}\selectfont\color{textgray}
  Deployment on a major scientific publishing platform}
}

% ══ COLUMN 2: KEY TAKEAWAYS ══
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=2, between=row16 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{enumerate}[itemsep=10pt]
    \item Bot traffic $\approx$ \textbf{half} of all publisher requests
    \item CDN-edge verification \textbf{blocks bots} with minimal human impact
    \item \textbf{Ray ID tracing} enables continuous security--usability optimization
    \item Publisher--CDN \textbf{collaboration} sustains open, secure science access
  \end{enumerate}
  \vspace{8pt}
  \centering
  {\fontsize{20}{26}\selectfont\color{textgray}
  Challenge-based pipelines: rigorous protection, minimal friction}
}

\end{tcbposter}
\end{document}

