python3 -c "
from PIL import Image
img = Image.open('/app/poster/poster_review.png')
width, height = img.size
# The title text might not be in that crop region
# Let's search the entire title bar for white pixels
title_bar = img.crop((0, 0, width, int(height*0.15)))
white_found = False
for y in range(title_bar.size[1]):
    for x in range(title_bar.size[0]):
        px = title_bar.getpixel((x, y))
        if px[0] > 240 and px[1] > 240 and px[2] > 240:
            print(f'First white pixel at ({x}, {y})')
            white_found = True
            break
    if white_found:
        break

if not white_found:
    print('No white pixels found in title bar!')
    # Maybe the text is light gray?
    for y in range(title_bar.size[1]):
        for x in range(title_bar.size[0]):
            px = title_bar.getpixel((x, y))
            if px[0] > 200 and px[1] > 200 and px[2] > 200:
                print(f'First light pixel at ({x}, {y}): {px}')
                break
        else:
            continue
        break
"
